import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"操作系统","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/操作系统.md","filePath":"专业基础/操作系统.md","lastUpdated":1792430298000}'),i={name:"专业基础/操作系统.md"};function d(o,t,h,n,s,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="操作系统" tabindex="-1">操作系统 <a class="header-anchor" href="#操作系统" aria-label="Permalink to &quot;操作系统&quot;">​</a></h1><blockquote><p>安全的主战场之一。校内对应「操作系统及安全」（第 4 学期）——操作系统本身就是课程的核心安全对象，进程、内存、文件系统处处是攻防的边界。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>绝大多数漏洞发生在操作系统与应用程序的边界（栈、堆、内核、权限）；</li><li>渗透测试、提权、应急响应都要求理解进程、文件权限、系统调用；</li><li>校内「操作系统及安全」直接考核系统安全机制（见 <a href="./../安全方向/操作系统安全.html">操作系统安全</a>）。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>进程与线程、调度</li><li>内存管理（虚拟内存、页表、地址空间）</li><li>文件系统与权限模型（Linux 权限、ACL、SELinux/AppArmor 概念）</li><li>系统调用与用户态/内核态</li><li>同步与死锁</li><li>安全相关：缓冲区、权限提升、隔离机制（进阶见操作系统安全页）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《操作系统导论》（OSTEP）</td><td>书</td><td><a href="https://ostep.org/" target="_blank" rel="noreferrer">ostep.org</a> 免费在线，OS 教学口碑最佳</td></tr><tr><td>校内教材 / 王道考研《操作系统》</td><td>教辅</td><td>应对考试与系统梳理</td></tr><tr><td>MIT 6.1810 (6.S081): Operating System Engineering</td><td>公开课</td><td>动手写操作系统的经典课程，Lab 含系统调用与页表实验</td></tr><tr><td>CSAPP 第 8 章（异常控制流）</td><td>书</td><td>与组成、OS 的衔接</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>把「权限与隔离」作为网安视角的主线：文件权限、SUID、用户态/内核态、容器隔离，逐一看懂；</li><li>动手：在 Linux 上练习进程管理、软硬链接权限、<code>strace</code> 跟踪系统调用；</li><li>想深入系统安全的同学，大三大四可以做 MIT 6.S081 的实验。</li></ul><h2 id="关联页面" tabindex="-1">关联页面 <a class="header-anchor" href="#关联页面" aria-label="Permalink to &quot;关联页面&quot;">​</a></h2><ul><li>进阶：<a href="./../安全方向/操作系统安全.html">操作系统安全</a></li><li>实验：<a href="./../实验与实践/安全实验平台.html">安全实验平台</a></li></ul>',12)])])}const b=a(i,[["render",d]]);export{_ as __pageData,b as default};
